const CELLS = new Map();
for (const [disp, s] of Object.entries(SYL)) CELLS.set(s.initial + '|' + s.final, disp);

// Display spelling for an (initial, final) grid cell, or null if no such syllable exists.
export function cell(initial, final) {
  return CELLS.get(initial + '|' + final) ?? null;
}

const MARKS = {
  a: 'āáǎà', e: 'ēéěè', i: 'īíǐì', o: 'ōóǒò', u: 'ūúǔù', v: 'ǖǘǚǜ',
};

// Tone-marked display for a numbered key, e.g. 'lv3' -> 'lǚ', 'hao3' -> 'hǎo', 'ma5' -> 'ma'.
export function toneMark(key) {
  const m = /^(.*?)([1-5])$/.exec(key);
  if (!m) return key;
  const s = m[1];
  const t = Number(m[2]);
  if (t === 5) return s.replace(/v/g, 'ü');
  let idx;
  if (s.includes('a')) idx = s.indexOf('a');
  else if (s.includes('e')) idx = s.indexOf('e');
  else if (s.includes('ou')) idx = s.indexOf('o');
  else idx = Math.max(...[...s].map((c, i) => ('aeiouv'.includes(c) ? i : -1)));
  const v = s[idx];
  const out = s.slice(0, idx) + MARKS[v][t - 1] + s.slice(idx + 1);
  return out.replace(/v/g, 'ü');
}
